import random
from collections import Counter

def task_func(strings: list) -> dict:
    pattern = globals().get("PATTERN", globals().get("pattern", "pattern"))
    if not isinstance(pattern, str) or pattern == "":
        pattern = "pattern"

    total = 0
    for s in strings or []:
        if not isinstance(s, str):
            s = str(s)
        total += s.count(pattern)

    return {"count": total}
